/**
 * The constants of command/.
 *
 * PAGE_SIZE: the size of the page a list gets when it names none.
 *
 * @example const page = { cursor: '', size: spec.pageSize ?? PAGE_SIZE };
 */
/** Fifty items: up to 50 a list is no long list yet (decision 56), so one page holds it whole. */
export const PAGE_SIZE = 50;
